import{_ as l,P as r,I as s,g as a,d as o,l as i,k as n,j as d}from"./chunks/framework.CjoWWfVe.js";const f=JSON.parse('{"title":"ПРО: Мультипространства и Личные финансы","description":"Управление несколькими бизнесами в одной программе, единый бэкап и революционная автоматическая консолидация личных трат.","frontmatter":{"title":"ПРО: Мультипространства и Личные финансы","description":"Управление несколькими бизнесами в одной программе, единый бэкап и революционная автоматическая консолидация личных трат.","order":15},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/pro-mode.md","filePath":"ru/docs/spaces/moy-kapital/pro-mode.md"}'),c={name:"ru/docs/spaces/moy-kapital/pro-mode.md"},p={id:"про-режим-экосистема-для-масштабирования",tabindex:"-1"};function g(h,t,u,m,b,k){const e=r("DocIcon");return s(),a("div",null,[o("h1",p,[i(e,{name:"pro"}),t[0]||(t[0]=n(" ПРО-режим: Экосистема для масштабирования ",-1)),t[1]||(t[1]=o("a",{class:"header-anchor",href:"#про-режим-экосистема-для-масштабирования","aria-label":'Permalink to "<DocIcon name="pro" /> ПРО-режим: Экосистема для масштабирования"'},"​",-1))]),t[2]||(t[2]=d('<p><strong>ПРО-режим</strong> — это премиум-архитектура ОмниКрафт ЕРП, которая превращает локальную программу из инструмента учёта одной мастерской в полноценную <strong>экосистему управления капиталом</strong>.</p><p>Этот режим открывает две революционные возможности:</p><ol><li><strong>Мультипространства (Multi-Workspaces):</strong> Ведение нескольких независимых бизнесов с изолированными базами данных.</li><li><strong>Глобальная вкладка «Мой капитал»:</strong> Автоматический учёт личных финансов через математическую дельту, без необходимости вбивать каждый чек за кофе.</li></ol><div class="info custom-block"><p class="custom-block-title">Как активировать ПРО?</p><p>ПРО-режим активируется флагом в вашем лицензионном ключе. Как только ключ с типом <code>Про</code> вводится во вкладке «Настройки», программа мгновенно разблокирует выдвижную боковую панель и глобальные инструменты консолидации.</p></div><hr><h2 id="мультипространства-multi-workspaces" tabindex="-1">Мультипространства (Multi-Workspaces) <a class="header-anchor" href="#мультипространства-multi-workspaces" aria-label="Permalink to &quot;Мультипространства (Multi-Workspaces)&quot;">​</a></h2><p>Многие ремесленники со временем запускают смежные направления: основная кожевенная мастерская, продажа электронных лекал, преподавание на курсах или ремонт изделий. Смешивать всё это в одной базе — плохая идея: разные валюты, разные наценки, разный склад и абсолютно разная экономика.</p><p>ПРО-режим позволяет создавать <strong>неограниченное количество изолированных рабочих пространств</strong>. Каждое пространство — это полноценная, отдельная база данных SQLite со своими справочниками, рецептами, складом и историей продаж.</p><h3 id="как-это-работает-боковая-шторка" tabindex="-1">Как это работает (Боковая шторка) <a class="header-anchor" href="#как-это-работает-боковая-шторка" aria-label="Permalink to &quot;Как это работает (Боковая шторка)&quot;">​</a></h3><p>В верхней правой части окна появляется кнопка <strong>«Пространства и Модули»</strong>. При нажатии на неё выезжает правая боковая шторка, которая становится вашим главным диспетчерским пультом.</p><p>В верхней секции шторки отображается список всех созданных вами пространств:</p><ul><li>🟢 <strong>Зелёная иконка:</strong> Текущее активное пространство, данные которого вы сейчас видите на экране.</li><li>⚪ <strong>Серая иконка:</strong> Другие зарегистрированные базы. Нажмите на них, чтобы мгновенно переключиться.</li></ul><p>При переключении программа на лету подменяет путь к активной базе данных. Интерфейс (вкладки Мастерской, Калькулятора, ДДС и т.д.) мгновенно перезагружается, подтягивая цифры, остатки и аналитику выбранного бизнеса.</p><h3 id="создание-нового-пространства" tabindex="-1">Создание нового пространства <a class="header-anchor" href="#создание-нового-пространства" aria-label="Permalink to &quot;Создание нового пространства&quot;">​</a></h3><p>Внизу списка находится кнопка <strong>«Добавить пространство»</strong>. При нажатии открывается диалог, где вы вводите понятное имя (например, <em>«Выкройки и ПДФ»</em> или <em>«Кожевенный ремонт»</em>).</p><p>Программа автоматически:</p><ol><li>Генерирует уникальный ID и создаёт новый физический файл базы данных в защищённой системной папке.</li><li>Инициализирует в нём все необходимые таблицы (Склад, Верстак, ДДС, Капитал и т.д.).</li><li>Регистрирует пространство в глобальном реестре <code>workspaces.json</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Изоляция данных</p><p>Пространства полностью независимы. У каждого бизнеса своя ставка мастера, своя глобальная наценка, свои статьи накладных расходов и свой склад сырья. Вы можете вести один бизнес в рублях, а второй — в долларах или евро, просто измени валюту учёта в настройках конкретного пространства.</p></div><hr><h2 id="единыи-глобальныи-бэкап" tabindex="-1">Единый глобальный бэкап <a class="header-anchor" href="#единыи-глобальныи-бэкап" aria-label="Permalink to &quot;Единый глобальный бэкап&quot;">​</a></h2><p>В ПРО-режиме система резервного копирования эволюционирует. Вместо того чтобы экспортировать каждую базу данных по отдельности, программа упаковывает <strong>абсолютно всё</strong> в один сжатый архив:</p><ul><li>🗃️ Реестр пространств (<code>workspaces.json</code>).</li><li>📦 Базу данных по умолчанию (<code>omnicraft_erp.db</code>).</li><li>📁 Всю папку <code>workspaces/</code> со всеми дополнительными бизнесами.</li><li>💳 Глобальную базу личных финансов (<code>personal_finance.db</code>).</li></ul><p>Это означает, что для полного переноса вашей экосистемы на новый компьютер или для создания страховочной копии вам достаточно сделать <strong>один клик</strong> в меню <code>Файл ➔ Экспорт данных</code>.</p><hr><h2 id="глобальная-вкладка-«мои-капитал»-личные-финансы" tabindex="-1">Глобальная вкладка «Мой капитал» (Личные финансы) <a class="header-anchor" href="#глобальная-вкладка-«мои-капитал»-личные-финансы" aria-label="Permalink to &quot;Глобальная вкладка «Мой капитал» (Личные финансы)&quot;">​</a></h2><p>Это, пожалуй, самая инновационная функция ОмниКрафт ЕРП. Она решает главную боль любого предпринимателя: <strong>как учитывать личные деньги, не превращаясь в бухгалтера, который вбивает в таблицу каждую покупку хлеба?</strong></p><p>В ПРО-режиме в боковой шторке появляется крупная кнопка <strong>«Мой капитал»</strong>. При её нажатии стандартные бизнес-вкладки скрываются, и открывается глобальная консолидация, выстроенная в виде удобной 5-вкладочной воронки:</p><h3 id="_1-счета-и-инвестиции-ликвидныи-контур" tabindex="-1">1. Счета и инвестиции (Ликвидный контур) <a class="header-anchor" href="#_1-счета-и-инвестиции-ликвидныи-контур" aria-label="Permalink to &quot;1. Счета и инвестиции (Ликвидный контур)&quot;">​</a></h3><p>Единый центр управления ликвидностью вне бизнеса, объединённый компактным сегментным переключателем:</p><ul><li><strong>Банковские счета и карты:</strong> дебетовые и кредитные карты, наличные средства в кошельках, накопительные счета, вклады и депозиты, валютные активы. Чтобы актуализировать баланс, достаточно периодически нажимать иконку карандаша и вписывать фактический остаток — программа сама зафиксирует дельту.</li><li><strong>Инвестиционный портфель:</strong> ценные бумаги (акции, облигации, биржевые фонды), доли в сторонних бизнесах и займы партнёрам с расчётом совокупной доходности и сегментной фильтрацией.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Где учитывать стейблкоины и USDT?</p><p>Расчётные стейблкоины (USDT, USDC) и криптовалютные кошельки, используемые как платёжное средство или резерв ликвидности, удобнее и правильнее вносить во вкладку <strong>«Банковские счета и карты»</strong> как валютные счета. Вкладка <strong>«Инвестиционный портфель»</strong> предназначена для активов с расчётом доходности, дивидендов и прироста тела капитала (акции, облигации, фонды, доли в бизнесах, займы).</p></div><h3 id="_2-имущество-и-материалы-единыи-материальныи-реестр" tabindex="-1">2. Имущество и материалы (Единый материальный реестр) <a class="header-anchor" href="#_2-имущество-и-материалы-единыи-материальныи-реестр" aria-label="Permalink to &quot;2. Имущество и материалы (Единый материальный реестр)&quot;">​</a></h3><p>Центральный реестр всех материальных активов мастера с 4 ключевыми карточками сводки (<code>Все имущество и материалы</code>, <code>Недвижимость и авто</code>, <code>Оборудование и станки</code>, <code>Сырьё и запасы</code>) и 4-сегментным фильтром:</p><ul><li><strong>Недвижимость и автомобили:</strong> личные квартиры, земля, рабочий и персональный транспорт, ценные вещи с возможностью постановки финансовых целей накопления.</li><li><strong>Оборудование и станки:</strong> парки машин, станки, инструменты мастерских с динамической амортизацией и точной настройкой долей владения.</li><li><strong>Материалы и запасы:</strong> складские остатки сырья, фурнитуры и расходных материалов по скользящей средней (MAC) со всех зарегистрированных складов.</li><li><strong>Доли владения (3-сторонний баланс Гамильтона):</strong> иконка диаграммы открывает редактор распределения актива между контурами: $\\text{Личное} + \\text{Производство} + \\text{Услуги} = 100.00%$ ($10,000\\text{ bp}$) с мгновенной автоматической балансировкой остатков.</li><li><strong>Защитные барьеры удаления (Deletion Guardrails):</strong> кнопка удаления проверяет наличие операционной истории (проводки в кассе ДДС, списания сырья, партии, ремонты). Если позиция участвовала в реальной работе цеха, прямое удаление блокируется для защиты от кассовых разрывов, а программа предлагает безопасное выбытие в Архив (<code>Продано</code>, <code>Утилизировано по износу</code>, <code>Подарено / выведено из эксплуатации</code>).</li><li><strong>Инспектор дубликатов и коллизий:</strong> аудит задвоенных карточек и расхождений в сумме долей владения.</li></ul><h3 id="_3-важные-операции" tabindex="-1">3. Важные операции <a class="header-anchor" href="#_3-важные-операции" aria-label="Permalink to &quot;3. Важные операции&quot;">​</a></h3><p>Журнал для учёта только <strong>существенных</strong> внешних потоков, которые нельзя игнорировать:</p><ul><li><em>Внешние доходы:</em> Зарплата по найму, разовый фриланс, дивиденды, крупные подарки.</li><li><em>Целевые расходы:</em> Крупные покупки, оплата обучения, медицинские услуги, погашение обязательств.</li></ul><h3 id="_4-мои-капитал-итоговая-сводка" tabindex="-1">4. Мой капитал (Итоговая сводка) <a class="header-anchor" href="#_4-мои-капитал-итоговая-сводка" aria-label="Permalink to &quot;4. Мой капитал (Итоговая сводка)&quot;">​</a></h3><p>Сердце раздела. Здесь программа сводит воедино данные всех ваших бизнес-пространств и личных счетов, рассчитывая ключевые показатели:</p><div class="tip custom-block"><p class="custom-block-title">Адаптация при первом запуске</p><p>Если личные счета и рабочие пространства ещё не сформированы, экран встречает понятной карточкой первого старта (Empty State) с кнопкой быстрого добавления первого счёта и возможностью ознакомиться с демонстрационным режимом.</p></div><ul><li><strong>Структура совокупного капитала:</strong> сквозной 4-столпный срез: <ol><li>💳 <strong>Счета (Деньги)</strong> — ликвидные остатки на картах, счетах и в наличных.</li><li>📈 <strong>Инвестиции</strong> — акции, облигации, фонды и криптоактивы.</li><li>🏠 <strong>Личные активы</strong> — недвижимость, автомобили, ценные вещи.</li><li>🏭 <strong>Имущество пространств</strong> — совокупная стоимость станков, оборудования, транспорта и складских запасов всех мастерских.</li></ol></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Показатель</th><th style="text-align:left;">Что означает</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>💎 Абсолютный капитал (Чистые активы)</strong></td><td style="text-align:left;">Сумма всех 4 столпов капитала (Счета + Инвестиции + Личные активы + Имущество пространств). Ваше совокупное богатство на текущую секунду.</td></tr><tr><td style="text-align:left;"><strong>💰 Заработано в бизнесах</strong></td><td style="text-align:left;">Консолидированная чистая прибыль со всех рабочих пространств за всё время.</td></tr><tr><td style="text-align:left;"><strong>📈 Внешние доходы / Накоплено</strong></td><td style="text-align:left;">Сумма всех важных личных доходов, не связанных с бизнесом.</td></tr><tr><td style="text-align:left;"><strong>🔍 Свободные траты на жизнь</strong></td><td style="text-align:left;">Та самая «магическая» цифра (см. ниже).</td></tr></tbody></table><h4 id="магическая-формула-свободных-трат" tabindex="-1">Магическая формула свободных трат <a class="header-anchor" href="#магическая-формула-свободных-трат" aria-label="Permalink to &quot;Магическая формула свободных трат&quot;">​</a></h4><p>Как программа узнаёт, сколько вы потратили на жизнь (еду, бензин, кофе, одежду), если вы не вбивали эти чеки? Она вычисляет их <strong>от обратного</strong>, через дельту капитала:</p><p>$$\\text{Свободные траты} = \\text{Прибыль бизнесов} + \\text{Внешние доходы} - \\text{Важные личные расходы} - \\text{Фактический прирост капитала}$$</p><p><strong>Как это работает на практике:</strong></p><ol><li>Программа видит, что ваш бизнес принес <code>100 000 ₽</code> чистой прибыли.</li><li>Вы получили зарплату на работе <code>50 000 ₽</code> (внесли как Внешний доход).</li><li>Вы внесли крупный платеж <code>30 000 ₽</code> (внесли как Важный расход).</li><li><em>Теоретически</em> у вас должно стать больше денег на <code>120 000 ₽</code>.</li><li>Но программа смотрит на ваши реальные банковские карты и видит, что суммарный остаток вырос только на <code>40 000 ₽</code>.</li><li><strong>Вывод:</strong> <code>80 000 ₽</code> вы незаметно потратили на повседневную жизнь. Программа честно покажет эту цифру в блоке «Свободные траты на жизнь».</li></ol><div class="tip custom-block"><p class="custom-block-title">Философия «Учёта без рутины»</p><p>Этот подход полностью избавляет вас от микроменеджмента личного бюджета. Вам не нужно сканировать чеки из супермаркета. Программа выступает в роли честного зеркала: она показывает, какой объем денег «растворяется» в быту, позволяя вам оценивать свой реальный уровень жизни и корректировать финансовые цели, опираясь на твердые математические факты.</p></div><h3 id="_5-аналитика" tabindex="-1">5. Аналитика <a class="header-anchor" href="#_5-аналитика" aria-label="Permalink to &quot;5. Аналитика&quot;">​</a></h3><p>Глубокий анализ совокупного капитала, структуры активов и распределения расходов:</p><ul><li><strong>Динамика чистого капитала:</strong> помесячный график роста богатства с гарантией сохранения истории удаленных мастерских.</li><li><strong>Структура распределения активов:</strong> соотношение свободных денег, мастерских, личных вещей и инвестиций.</li><li><strong>Тренды свободных расходов:</strong> автоматический расчет повседневных расходов на жизнь.</li><li><strong>Стартовая заглушка:</strong> при отсутствии данных вкладка встречает аккуратным экраном первичного входа со ссылкой на добавление первого счета и кнопкой запуска демонстрационного режима.</li><li><strong>🛡️ Непрерывность истории и срезы удалённых пространств (Этап M5):</strong> при ликвидации или окончательном удалении ненужного бизнес-пространства его файл операционной базы данных безопасно очищается с диска, но система автоматически сохраняет в глобальном реестре компактный помесячный статистический срез (выручка, себестоимость, расходы, амортизация и капитал). Это гарантирует, что ретроспективный график динамики чистых активов в «Моём капитале» никогда не получит провалов и искажений за прошлые периоды, сохраняя полную финансовую историю мастера.</li></ul><hr><h2 id="сквозные-тематические-модули-дополнении" tabindex="-1">Сквозные тематические модули (дополнений) <a class="header-anchor" href="#сквозные-тематические-модули-дополнении" aria-label="Permalink to &quot;Сквозные тематические модули (дополнений)&quot;">​</a></h2><p>В будущем в нижней секции выдвижной шторки будут появляться <strong>Сквозные модули</strong> — нишевые инструменты, которые можно докупать отдельно.</p><p>Они называются «сквозными», потому что <strong>не привязаны к конкретной базе данных</strong>. Например, модуль «Амбассадор» доступен вам из любого активного рабочего пространства, позволяя вести продвижение и управлять партнерскими кампаниями для всех ваших направлений бизнеса.</p><p>Управление модулями и их статусом также централизовано в боковой шторке и привязано к вашему единому лицензионному ключу, который «эволюционирует» по мере расширения вашей экосистемы.</p>',56))])}const _=l(c,[["render",g]]);export{f as __pageData,_ as default};
